let lang = (()=>{try{const v=localStorage.getItem('ticketdesk-language')||'en';return ['en','th'].includes(v)?v:'en';}catch{return 'en';}})();
let themePref=(()=>{try{return localStorage.getItem('ticketdesk-theme')||'light';}catch{return 'light';}})();
