async function orderReportSnapshots(report){
 const snapshots=Array.isArray(report?.ticketSnapshots)?report.ticketSnapshots.slice():[];
 const tickets=await ticketsFor(report.departmentId),positions=new Map(tickets.map((t,i)=>[t.id,i]));
 return snapshots.map((t,i)=>({t,i})).sort((a,b)=>{
  const ai=positions.has(a.t.ticketId)?positions.get(a.t.ticketId):Number.MAX_SAFE_INTEGER;
  const bi=positions.has(b.t.ticketId)?positions.get(b.t.ticketId):Number.MAX_SAFE_INTEGER;
  return ai-bi||a.i-b.i;
 }).map(x=>x.t);
}
