async function renderReports(){let reports=(await all('reports')).filter(r=>reportFilterDept==='all'||r.departmentId===reportFilterDept);if(reportFrom)reports=reports.filter(r=>(r.reportPeriodEnd||r.reportDate)>=reportFrom);if(reportTo)reports=reports.filter(r=>(r.reportPeriodStart||r.reportDate)<=reportTo);if(searchText)reports=reports.filter(r=>String(r.reportDate||'').includes(searchText)||String(r.reportPeriodStart||'').includes(searchText)||(Array.isArray(r.ticketSnapshots)&&r.ticketSnapshots.some(t=>String(t?.name||'').toLowerCase().includes(searchText.toLowerCase()))));reports.sort((a,b)=>reportSort==='newest'?String(b.reportDate||'').localeCompare(String(a.reportDate||''))||String(b.createdAt||'').localeCompare(String(a.createdAt||'')):String(a.reportDate||'').localeCompare(String(b.reportDate||''))||String(a.createdAt||'').localeCompare(String(b.createdAt||'')));const monthDefault=(selectedDate||localDate()).slice(0,7);$('#appContent').innerHTML=`<div class="page-head"><div><h2>${tr('reportHistory')}</h2><p>${tr('snapshotWarning')}</p></div></div><div class="panel"><h3>${lang==='th'?'บันทึกรายงานรายเดือน':'Save Monthly Report'}</h3><p class="muted">${lang==='th'?'รวมจำนวนตั๋วรายวันของเดือนที่เลือกและบันทึกเป็นรายงานถาวร':'Combine daily ticket quantities for the selected month and save a permanent monthly snapshot.'}</p><div class="toolbar" style="margin:0"><div class="toolbar-left"><input id="monthlyReportMonth" class="date-input" type="month" value="${monthDefault}"><select id="monthlyReportDept" class="date-input"><option value="all">${tr('allDepartments')}</option>${DEPTS.map(d=>`<option value="${d.id}">${esc(tx(d.title))}</option>`).join('')}</select></div><div class="toolbar-right"><button class="btn btn-primary" id="saveMonthlyReport">${lang==='th'?'บันทึกรายงานรายเดือน':'Save Monthly Report'}</button></div></div></div><div class="panel"><div class="toolbar" style="margin:0"><div class="toolbar-left"><select id="reportDeptFilter" class="date-input"><option value="all">${tr('allDepartments')}</option>${DEPTS.map(d=>`<option value="${d.id}" ${reportFilterDept===d.id?'selected':''}>${tx(d.title)}</option>`).join('')}</select><input id="reportSearch" class="search-input" placeholder="${tr('searchReports')}" value="${esc(searchText)}"></div><div class="toolbar-right"><input id="reportFrom" class="date-input" type="date" value="${reportFrom}" aria-label="${tr('from')}"><input id="reportTo" class="date-input" type="date" value="${reportTo}" aria-label="${tr('to')}"><select id="reportSort" class="date-input"><option value="newest" ${reportSort==='newest'?'selected':''}>${tr('newest')}</option><option value="oldest" ${reportSort==='oldest'?'selected':''}>${tr('oldest')}</option></select></div></div></div>${reports.length?`<div class="report-list">${reports.map(r=>`<article class="report-card"><div class="dept-title">${esc(tx(dept(r.departmentId).title))} ${r.reportType==='monthly'?'· '+(lang==='th'?'รายงานรายเดือน':'Monthly Report'):''}</div><div class="report-meta"><span>◷ ${r.reportType==='monthly'?esc(r.reportPeriodStart)+' – '+esc(r.reportPeriodEnd):fmtDate(r.reportDate)}</span><span>${tr('version')} ${r.reportVersion||1}</span><span>${fmtNum(r.ticketTypeCount)} ${tr('types')}</span></div><div class="report-total">${fmtNum(r.totalQuantity)} <span class="muted" style="font-size:12px;font-weight:500">${tr('total').toLowerCase()}</span></div><div class="report-meta">${tr('created')}: ${new Date(r.createdAt).toLocaleString(lang==='th'?'th-TH':'en-GB')}</div><div class="report-actions"><button class="btn btn-primary btn-small" data-report-open="${r.id}">${tr('open')}</button><button class="btn btn-secondary btn-small" data-report-print="${r.id}">${tr('print')}</button><button class="btn btn-secondary btn-small" data-report-csv="${r.id}">${tr('csv')}</button><button class="btn btn-danger btn-small" data-report-delete="${r.id}">${tr('deleteReport')}</button></div></article>`).join('')}</div>`:`<div class="empty-state"><div class="empty-icon">▤</div><strong>${tr('noReports')}</strong><p>${tr('noMatch')}</p></div>`}`;}
async function saveMonthlyReport(){const month=$('#monthlyReportMonth')?.value;if(!month||!/^\d{4}-\d{2}$/.test(month)){toast(lang==='th'?'လကို ရွေးပါ':'Please choose a month','error');return;}const chosen=$('#monthlyReportDept')?.value||'all';const start=month+'-01',end=month+'-'+String(new Date(Number(month.slice(0,4)),Number(month.slice(5,7)),0).getDate()).padStart(2,'0');const departments=chosen==='all'?DEPTS:DEPTS.filter(d=>d.id===chosen);const daily=await all('daily');const allReports=await all('reports');let saved=0;for(const d of departments){const existing=allReports.filter(r=>r.reportType==='monthly'&&r.departmentId===d.id&&r.reportMonth===month).sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||'')));if(existing.length&&!confirmBox((lang==='th'?'လစဉ် Report ရှိပြီးသားဖြစ်သည်။ အသစ်ထပ်သိမ်းမလား? ':'A monthly report already exists for ')+tx(d.title)+' · '+month+(lang==='th'?'။ အသစ်သိမ်းမည်လား?':' . Save another version?')))continue;const tickets=await realTickets(d.id);const snaps=[];for(const t of tickets){const entries=daily.filter(x=>x.departmentId===d.id&&x.ticketId===t.id&&x.date>=start&&x.date<=end);const quantity=entries.reduce((sum,x)=>sum+(Number(x.quantity)||0),0);snaps.push({ticketId:t.id,name:t.name,imageData:t.imageId?await imageData(t.imageId):null,quantity,notes:t.notes||'',inventory:t.inventory??null,daysRecorded:entries.length,dailyBreakdown:entries.map(x=>({date:x.date,quantity:Number(x.quantity)||0})).sort((a,b)=>a.date.localeCompare(b.date))});}const total=snaps.reduce((sum,t)=>sum+(Number(t.quantity)||0),0);const createdAt=new Date().toISOString();await put('reports',{id:uid(),departmentId:d.id,reportDate:start,reportPeriodStart:start,reportPeriodEnd:end,reportMonth:month,reportType:'monthly',createdAt,ticketSnapshots:snaps,totalQuantity:total,ticketTypeCount:snaps.length,reportVersion:existing.length?Math.max(...existing.map(r=>Number(r.reportVersion)||1))+1:1});saved++;}if(saved){toast(lang==='th'?'လစဉ် Report သိမ်းပြီးပါပြီ':'Monthly report saved');reportFrom='';reportTo='';searchText='';renderReports();}else toast(lang==='th'?'Report အသစ်မသိမ်းခဲ့ပါ':'No monthly report was saved','error');}
async function renderOwnerDatabase(){const [tickets,daily,reports,images]=await Promise.all([all('tickets'),all('daily'),all('reports'),all('images')]);const named=tickets.filter(t=>String(t.name||'').trim());const staffLink='https://pattayadinosaurkingdom-chi.vercel.app/staff-portal.html';let loginHistory='<p class="muted">Loading login history…</p>';if(window.ticketdeskLoadStaffHistory){try{loginHistory=await window.ticketdeskLoadStaffHistory();}catch(e){loginHistory='<p class="notice">Could not load staff login history. Check Firestore Rules and deploy them in Firebase Console.</p>';}}$('#appContent').innerHTML=`<div class="page-head"><div><h2>${tr('ownerDbTitle')}</h2><p>${tr('ownerDbDesc')}</p></div><span class="badge">${tr('localOnlyMode')}</span></div><div class="stats-grid"><section class="stat-card"><div class="muted">${tr('tickets')}</div><div class="stat-number">${fmtNum(named.length)}</div><div class="stat-sub">${tr('records')}</div></section><section class="stat-card"><div class="muted">${tr('dailyActivity')}</div><div class="stat-number">${fmtNum(daily.length)}</div><div class="stat-sub">${tr('records')}</div></section><section class="stat-card"><div class="muted">${tr('savedReports')}</div><div class="stat-number">${fmtNum(reports.length)}</div><div class="stat-sub">${tr('records')}</div></section><section class="stat-card"><div class="muted">${tr('image')}</div><div class="stat-number">${fmtNum(images.length)}</div><div class="stat-sub">${tr('records')}</div></section></div><section class="panel"><h3>Staff Share Link</h3><p class="muted">Share this link with staff so they can enter their name and department.</p><p><a href="${staffLink}" target="_blank" rel="noopener">${staffLink}</a></p><button type="button" class="btn btn-secondary" id="copyStaffLink">Copy staff link</button><p class="help-text">The name is entered by the person using the link and is not identity-verified.</p></section><section class="panel"><h3>Staff Login History</h3><p class="muted">Recent check-ins submitted through the staff link.</p><div id="staffLoginHistory">${loginHistory}</div><button type="button" class="btn btn-secondary" id="refreshStaffHistory">Refresh history</button></section><section class="panel"><h3>Staff Accounts — Usage & Access</h3><p class="muted">Account activity is based on the latest check-in, not a guaranteed live-online indicator. Recently used means a check-in in the last 15 minutes.</p><div id="staffAccountList"><p class="muted">Loading staff accounts…</p></div><button type="button" class="btn btn-secondary" id="refreshStaffAccounts">Refresh staff accounts</button></section><section class="panel"><h3>${tr('staffAccounts')}</h3><p class="muted">${tr('staffPermissions')}: ${tr('staffScope')}. ${tr('staffNoDelete')}.</p><div class="notice">${tr('cloudRequired')}</div><button class="btn btn-secondary" data-nav="backup">${tr('backupTitle')} →</button></section><section class="panel"><h3>${tr('department')}</h3>${DEPTS.map(d=>{const rows=named.filter(t=>t.departmentId===d.id);return `<div class="summary-line"><span>${esc(tx(d.title))}</span><strong>${fmtNum(rows.length)} ${tr('tickets').toLowerCase()}</strong></div>`;}).join('')}</section>`;const copy=$('#copyStaffLink');if(copy)copy.onclick=async()=>{try{await navigator.clipboard.writeText(staffLink);toast('Staff link copied');}catch{toast('Copy failed. Select and copy the link above.','error');}};const refresh=$('#refreshStaffHistory');if(refresh)refresh.onclick=()=>renderOwnerDatabase();if(window.ticketdeskLoadStaffAccounts){try{await window.ticketdeskLoadStaffAccounts();}catch(e){console.warn('Staff account list did not load',e);}}}
