function exportCSV(r){if(r.reportType==='monthly'){const rows=[];for(const t of (r.ticketSnapshots||[])){const days=Array.isArray(t.dailyBreakdown)?t.dailyBreakdown:[];if(days.length){for(const d of days)rows.push({date:d.date,name:t.name||'',image:t.imageData||'',quantity:Number(d.quantity)||0});}else rows.push({date:r.reportPeriodStart||r.reportDate,name:t.name||'',image:t.imageData||'',quantity:Number(t.quantity)||0});}const escHtml=v=>String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');const body=rows.map(x=>'<tr><td>'+escHtml(x.date)+'</td><td>'+escHtml(x.name)+'</td><td>'+(String(x.image).startsWith('data:image/')?'<img src="'+x.image+'" width="90" height="60">':'')+'</td><td style="mso-number-format:0">'+x.quantity+'</td></tr>').join('');const html='<!DOCTYPE html><html><head><meta charset="utf-8"><style>table{border-collapse:collapse}th,td{border:1px solid #888;padding:6px}th{background:#dce6f1}img{object-fit:contain}</style></head><body><h2>Pattaya Dinosaur Kingdom — Monthly Ticket Report</h2><p>'+escHtml(r.reportPeriodStart||r.reportDate)+' – '+escHtml(r.reportPeriodEnd||r.reportDate)+' | '+escHtml(tx(dept(r.departmentId).title))+'</p><table><thead><tr><th>Date</th><th>Ticket name</th><th>Ticket image</th><th>Quantity</th></tr></thead><tbody>'+body+'</tbody><tfoot><tr><th colspan="3">Monthly total</th><th>'+Number(r.totalQuantity||0)+'</th></tr></tfoot></table></body></html>';downloadBlob(new Blob(['\ufeff',html],{type:'application/vnd.ms-excel;charset=utf-8;'}),`monthly-ticket-report-${r.departmentId}-${r.reportMonth||r.reportDate}-v${r.reportVersion||1}.xls`);return;}const rows=[[tr('department'),tx(dept(r.departmentId).title)],[tr('reportDate'),r.reportDate],[tr('version'),r.reportVersion||1],[],[tr('name'),tr('quantity'),tr('notes')],...r.ticketSnapshots.map(t=>[t.name,t.quantity,t.notes||'']),[],[tr('total'),r.totalQuantity]];const csv=rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');downloadBlob(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'}),`ticket-report-${r.departmentId}-${r.reportDate}-v${r.reportVersion||1}.csv`);}
